from math import ceil, log10

def graceful_tipping(bill):
    bill *= 1.15
    if bill < 10:
        return ceil(bill)
    e = int(log10(bill))
    unit = (10 ** e) / 2
    if 10 <= bill < 15:
        return ceil(bill / unit) * unit
    elif 15 <= bill < 20:
        return ceil(bill / unit) * unit + (unit // 5)
    elif 20 <= bill < 25:
        return ceil(bill / unit) * unit - (unit // 5)
    elif 25 <= bill < 30:
        return ceil(bill / unit) * unit - (unit // 50)
    elif 30 <= bill < 35:
        return ceil(bill / unit) * unit + (unit // 50)
    elif 35 <= bill < 40:
        return ceil(bill / unit) * unit - (unit // 500)
    elif 40 <= bill < 45:
        return ceil(bill / unit) * unit + (unit // 500)
    else:
        return ceil(bill / unit) * unit
```
